private volatile Frame current = Frame.EMPTY;   // written by ONE thread only

void publish() {
    current = renderNextFrame();                // release; readers see a whole frame
}

Frame snapshot() { return current; }             // volatile read, no lock

BufferStrategy strategy = canvas.getBufferStrategy();
do {
    do {
        Graphics g = strategy.getDrawGraphics();
        try { drawFrame(g); } finally { g.dispose(); }
    } while (strategy.contentsRestored());
    strategy.show();                 // present the finished frame
} while (strategy.contentsLost());
